request_payload.query:
query CustomerReviewList_Init($skuId: String!, $onlyIfRelated: Boolean = true) {
  ...CustomerReviewList_Fragment
}

fragment CustomerReviewList_Fragment on Query {
  productBySkuId(skuId: $skuId) {
    reviews(filter: {page: 1, pageSize: 3, sortBy: BEST_MATCH}) {
      results {
        badges {
          code
          description
          name
          __typename
        }
        daysOfOwnership
        id
        images {
          id
          piscesUrl
          __typename
        }
        rating
        submissionTime
        text
        title
        userNickname
        reviewedProduct(onlyIfRelated: $onlyIfRelated) {
          dotComDisplayStatus
          name {
            short
            __typename
          }
          skuId
          url {
            relativePdp
            __typename
          }
          __typename
          openBoxCondition
        }
        __typename
      }
      __typename
    }
    __typename
    skuId
    openBoxCondition
  }
  __typename
}
